<section class="hero"><div><p class="eyebrow">FOR THE LOVE OF A GOOD STORY</p><h1>Your next chapter<br>starts here<span>.</span></h1><p class="lead">Find your next favorite. Share what stayed with you.<br>A home for readers and the books they love.</p>{% if not g.user %}<a class="button" href="{{ url_for('signup') }}">Start your reading story <span aria-hidden="true">↗</span></a>{% endif %}</div><div class="hero-art" aria-hidden="true"><div class="art-book one">THE<br>WORLDS<br>WITHIN<small>A READER'S LIFE</small></div><div class="art-book two">ONE MORE<br>CHAPTER<small>BOOKSHELF COLLECTION</small></div><div class="art-caption">GOOD BOOKS. BETTER CONVERSATIONS.</div></div></section>
<section class="catalog"><div class="section-head"><div><p class="eyebrow">THE COMMUNITY SHELF</p><h2>{% if query %}Search results{% else %}Stories worth exploring{% endif %}</h2></div><span class="muted">{{ books|length }} books</span></div>
<form class="search" action="{{ url_for('browse') }}" method="get"><label for="q" class="sr-only">Search title or author</label><span aria-hidden="true">⌕</span><input id="q" name="q" value="{{ query }}" placeholder="Search by title or author" maxlength="200"><button class="button small">Search</button>{% if query %}<a href="{{ url_for('browse') }}">Clear</a>{% endif %}</form>
<div class="book-grid">{% for book in books %}<a class="book-card" href="{{ url_for('book_detail', book_id=book.id) }}"><div class="cover palette-{{ book.id % 6 }}"><span class="cover-author">{{ book.author }}</span><span class="cover-rule"></span><span class="cover-title">{{ book.title }}</span><span class="cover-symbol" aria-hidden="true">✳</span><span class="cover-bottom">THE BOOKSHELF EDITION</span></div><p class="genre">{{ book.genre }}</p><h3>{{ book.title }}</h3><p class="muted">{{ book.author }}</p></a>{% else %}<div class="empty"><h3>No books found.</h3><p>Try another title or author.</p></div>{% endfor %}</div></section>{% endblock %}
EOF
cat > demo-app/templates/auth.html <<'EOF'
{% extends 'base.html' %}{% block title %}{{ 'Sign up' if signup else 'Log in' }}{% endblock %}{% block content %}<section class="auth-layout"><div class="auth-copy"><p class="eyebrow">A PLACE ON THE SHELF</p><h1>{{ 'Every reader has a story.' if signup else 'Welcome back, reader.' }}</h1><p class="lead">{{ 'Make this one yours. Discover books and leave a little of yourself in every review.' if signup else 'Your next great read is waiting. Pick up where you left off.' }}</p><div class="quote">“A room without books is like a body without a soul.”<span>— Cicero</span></div></div><div class="panel"><h2>{{ 'Join BookShelf' if signup else 'Log in' }}</h2><p class="muted">{{ 'Your reading life, all in one place.' if signup else 'Good to have you on the shelf again.' }}</p><form method="post" class="stack"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label for="username">Username</label><input id="username" name="username" autocomplete="username" minlength="3" maxlength="30" required value="{{ request.form.get('username', '') }}">{% if signup %}<small>3–30 letters, numbers or underscores.</small>{% endif %}<label for="password">Password</label><input id="password" name="password" type="password" autocomplete="{{ 'new-password' if signup else 'current-password' }}" minlength="{{ 8 if signup else 1 }}" maxlength="128" required>{% if signup %}<small>At least 8 characters.</small>{% endif %}<button class="button">{{ 'Create account' if signup else 'Log in' }}</button></form><p class="auth-switch">{{ 'Already a member?' if signup else 'New here?' }} <a href="{{ url_for('login') if signup else url_for('signup') }}">{{ 'Log in' if signup else 'Create an account' }}</a></p></div></section>{% endblock %}
EOF
cat > demo-app/templates/edit_profile.html <<'EOF'
{% extends 'base.html' %}{% block title %}Edit profile{% endblock %}{% block content %}<section class="narrow"><p class="eyebrow">YOUR READING IDENTITY</p><h1 class="page-title">Make it yours.</h1><p class="lead">Tell the shelf a little about the reader behind the reviews.</p><form method="post" class="panel stack"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label for="display_name">Display name</label><input id="display_name" name="display_name" value="{{ request.form.get('display_name', g.user.display_name) }}" maxlength="60" required><label for="bio">Short bio</label><textarea id="bio" name="bio" rows="5" maxlength="500" placeholder="What stories do you gravitate toward?">{{ request.form.get('bio', g.user.bio) }}</textarea><label for="favorite_genre">Favorite genre</label><input id="favorite_genre" name="favorite_genre" value="{{ request.form.get('favorite_genre', g.user.favorite_genre) }}" maxlength="60" placeholder="Fantasy, classics, a little of everything…"><div class="actions"><button class="button">Save profile</button><a href="{{ url_for('profile', user_id=g.user.id) }}">Cancel</a></div></form></section>{% endblock %}
EOF
cat > demo-app/templates/profile.html <<'EOF'
{% extends 'base.html' %}{% block title %}{{ user.display_name }}{% endblock %}{% block content %}<section class="profile-header"><div class="avatar">{{ user.display_name[:1]|upper }}</div><div><p class="eyebrow">READER PROFILE</p><h1 class="page-title">{{ user.display_name }}</h1><p class="muted">@{{ user.username }}</p><p class="preserve">{{ user.bio or 'This reader is still writing their story.' }}</p>{% if user.favorite_genre %}<span class="tag">{{ user.favorite_genre }}</span>{% endif %}</div>{% if g.user and g.user.id == user.id %}<a class="button secondary" href="{{ url_for('edit_profile', user_id=user.id) }}">Edit profile</a>{% endif %}</section><section class="reviews-section"><div class="section-head"><h2>From this reader</h2><span class="muted">{{ reviews|length }} reviews</span></div>{% for review in reviews %}<article class="review"><a class="review-book" href="{{ url_for('book_detail', book_id=review.book_id) }}">{{ review.title }} ↗</a><time datetime="{{ review.created_at }}">{{ review.created_at }}</time><p class="preserve">{{ review.review_text }}</p></article>{% else %}<div class="empty"><h3>A fresh page.</h3><p>No reviews yet. Every reading story starts somewhere.</p><a href="{{ url_for('browse') }}">Find a book to review →</a></div>{% endfor %}</section>{% endblock %}
EOF
cat > demo-app/templates/book.html <<'EOF'
{% extends 'base.html' %}{% block title %}{{ book.title }}{% endblock %}{% block content %}<a class="back-link" href="{{ url_for('browse') }}">← Back to the shelf</a><section class="book-detail"><div class="cover palette-{{ book.id % 6 }}"><span class="cover-author">{{ book.author }}</span><span class="cover-rule"></span><span class="cover-title">{{ book.title }}</span><span class="cover-symbol" aria-hidden="true">✳</span><span class="cover-bottom">THE BOOKSHELF EDITION</span></div><div><p class="eyebrow">ON THE SHELF</p><h1 class="page-title">{{ book.title }}</h1><p class="book-author">by {{ book.author }}</p><span class="tag">{{ book.genre }}</span><p class="lead description">{{ book.description }}</p><p class="muted">{{ reviews|length }} community reviews · A story, many perspectives.</p></div></section><section class="review-layout"><div><div class="section-head"><h2>The conversation</h2><span class="muted">{{ reviews|length }} reviews</span></div>{% for review in reviews %}<article class="review"><div class="review-meta"><a href="{{ url_for('profile', user_id=review.user_id) }}">{{ review.display_name }}</a><time datetime="{{ review.created_at }}">{{ review.created_at }}</time></div><p class="preserve">{{ review.review_text }}</p></article>{% else %}<div class="empty"><h3>The first word is yours.</h3><p>No reviews yet. What did this book leave you thinking about?</p></div>{% endfor %}</div><aside class="panel review-form"><p class="eyebrow">YOUR TAKE</p><h2>Leave a little ink.</h2>{% if g.user %}<form method="post" action="{{ url_for('add_review', book_id=book.id) }}" class="stack"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label for="review_text">Your review</label><textarea id="review_text" name="review_text" rows="7" maxlength="5000" required placeholder="The moments that stayed with you…"></textarea><small>Up to 5,000 characters. Be thoughtful, be yourself.</small><button class="button">Publish review</button></form>{% else %}<p class="muted">Join the conversation. Log in to share your thoughts.</p><a class="button" href="{{ url_for('login') }}">Log in to review</a>{% endif %}</aside></section>{% endblock %}
EOF
