e{font-size:9px;text-transform:uppercase;letter-spacing:1.4px;color:var(--green);margin:16px 0 6px}.book-card h3{font-size:16px;margin:0 0 4px}.book-card .muted{font-size:13px;margin:0}.footer{border-top:1px solid var(--line);margin-top:75px;min-height:120px;display:flex;align-items:center;justify-content:space-between;gap:20px;color:var(--muted);font-size:12px}.footer .brand{font-size:19px;color:var(--ink)}.local-label{font-size:9px;letter-spacing:1.5px}.panel{background:#fff;border:1px solid var(--line);border-radius:10px;padding:32px}.auth-layout{display:grid;grid-template-columns:1fr 1fr;gap:85px;align-items:center;padding:75px 0;max-width:1000px;margin:auto}.auth-copy h1{font-size:47px}.quote{font-family:var(--serif);font-size:22px;padding-top:30px;border-top:1px solid var(--line);color:#56685e}.quote span{display:block;font:12px system-ui;margin-top:14px}.stack{display:flex;flex-direction:column;gap:10px}.stack label{font-weight:600;font-size:13px;margin-top:10px}.stack input,.stack textarea{padding:12px;background:#fbfcf9;border:1px solid #cfd6cc;border-radius:5px;width:100%;color:var(--ink)}textarea{resize:vertical}.stack .button{margin-top:15px}.stack small{font-size:11px}.auth-switch{font-size:13px;text-align:center;margin:22px 0 0}.auth-switch a{color:var(--green);font-weight:600}.narrow{max-width:650px;margin:60px auto}.page-title{font-size:42px}.notice{padding:14px 18px;background:#e5eee5;border-radius:6px;margin-top:22px}.notice.error{background:#f7e6df;color:#873c28}.profile-header{display:flex;gap:30px;align-items:flex-start;padding:60px 0;border-bottom:1px solid var(--line)}.avatar{width:90px;height:90px;flex-shrink:0;display:grid;place-items:center;background:#e3e9dc;color:var(--green);font:40px var(--serif);border-radius:50%}.profile-header .page-title{margin-bottom:8px}.profile-header .button{margin-left:auto;flex-shrink:0}.tag{display:inline-block;border:1px solid #cdd8c8;color:var(--green);padding:4px 12px;border-radius:30px;font-size:12px}.pre