<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{% block title %}BookShelf{% endblock %} · BookShelf</title><link rel="stylesheet" href="{{ url_for('static', filename='css/style.css') }}"></head>
<body>
<header class="site-header"><nav class="nav shell" aria-label="Main navigation"><a class="brand" href="{{ url_for('browse') }}"><span class="brand-icon">▥</span> BookShelf<span class="brand-dot">.</span></a><div class="nav-links"><a href="{{ url_for('browse') }}">Explore</a>{% if g.user %}<a href="{{ url_for('profile', user_id=g.user.id) }}">My profile</a><form action="{{ url_for('logout') }}" method="post"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><button class="text-button">Log out</button></form>{% else %}<a href="{{ url_for('login') }}">Log in</a><a class="button small" href="{{ url_for('signup') }}">Join the shelf</a>{% endif %}</div></nav></header>
